caracteristiques=COALESCE(cp.caracteristiques,'{}'::jsonb) || jsonb_build_object('type_isolant','PSE','epaisseur_nominale','130 mm','epaisseur_mm',130,'resistance_thermique_R_m2K_W',3.4,'conductivite_thermique_lambda_W_mK','0.038','prix_fourniture_ht_m2',0,'prix_pose_ht_m2',28.44,'pose_generee_comme_ligne_separee',true,'description_devis','Panneau de polystyrène expansé ignifugé SINIAT Unimat TH38 IGN, épaisseur 130 mm, résistance thermique R = 3,40 m²·K/W et conductivité λ = 0,038 W/(m·K), selon les données communiquées. Destination : isolation thermique du plancher bas. Prix de fourniture à renseigner avant émission du devis. Confirmer la référence exacte, le domaine d’emploi, la résistance mécanique et la compatibilité avec le complexe de plancher envisagé. Mise en œuvre selon la notice fabricant et traitement des rives et raccords. Surface selon métrage. Pose séparée à 28,44 € HT/m².','description_visible_devis',true,'prix_a_renseigner',true)
WHERE cp.id IN (SELECT id FROM cible);
