SELECT e.id,'plancher','Soprema Efisol TMS — 68 mm','Soprema','SOPREMA-EFISOL-TMS-68','Panneau rigide en polyuréthane (PIR/PU) SOPREMA Efisol TMS, épaisseur 68 mm, résistance thermique R = 3,15 m²·K/W et conductivité λ = 0,022 W/(m·K), selon les informations communiquées. Destination : isolation thermique du plancher bas sous chape. Vérifier la compatibilité avec le support, la chape, les charges, les joints et les prescriptions de pose du fabricant. Réaliser une couche isolante continue, avec traitement des rives et points singuliers. Surface facturée selon métrage du chantier. Fourniture seule ; pose chiffrée séparément à 28,44 € HT/m². Éligibilité aux aides à vérifier sur justificatifs et réglementation en vigueur.',jsonb_build_object('type_isolant','PU','epaisseur_nominale','68 mm','epaisseur_mm',68,'resistance_thermique_R_m2K_W',3.15,'conductivite_thermique_lambda_W_mK','0.022','prix_fourniture_ht_m2',15.7,'prix_pose_ht_m2',28.44,'pose_generee_comme_ligne_separee',true,'description_devis','Panneau rigide en polyuréthane (PIR/PU) SOPREMA Efisol TMS, épaisseur 68 mm, résistance thermique R = 3,15 m²·K/W et conductivité λ = 0,022 W/(m·K), selon les informations communiquées. Destination : isolation thermique du plancher bas sous chape. Vérifier la compatibilité avec le support, la chape, les charges, les joints et les prescriptions de pose du fabricant. Réaliser une couche isolante continue, avec traitement des rives et points singuliers. Surface facturée selon métrage du chantier. Fourniture seule ; pose chiffrée séparément à 28,44 € HT/m². Éligibilité aux aides à vérifier sur justificatifs et réglementation en vigueur.','description_visible_devis',true,'prix_a_renseigner',false),15.7,'m2',20,false,false,'',true,28.44,0,'particulier','particulier'
FROM entreprises e WHERE NOT EXISTS (SELECT 1 FROM catalogue_produits cp WHERE cp.categorie='plancher' AND cp.reference='SOPREMA-EFISOL-TMS-68') ORDER BY e.created_at LIMIT 1;
